(() => {
  const STORE='wicho-animacion-editor-v1', DB='wicho-animacion-images-v1';
  const defaults=JSON.parse(JSON.stringify(window.animacionContent));
  const $=(s,r=document)=>r.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeUrl=value=>{try{const u=new URL(value,location.href);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
  const watchUrl=id=>`https://www.youtube.com/watch?v=${encodeURIComponent(id||'')}`;
  const thumbFor=(id,alt=false)=>`https://i.ytimg.com/vi/${encodeURIComponent(id||'')}/${alt?'hqdefault':'maxresdefault'}.jpg`;
  let state=readState(), dbPromise, objectUrls=[]; const status=$('#adminStatus');
  function readState(){try{const s=JSON.parse(localStorage.getItem(STORE)||'null');if(s?.content?.stories&&s.content?.copy)return s}catch(e){console.warn('No se pudo leer el contenido guardado.',e)}return {content:JSON.parse(JSON.stringify(defaults)),bannerKey:''}}
  function save(message='Cambios guardados en este navegador.'){try{localStorage.setItem(STORE,JSON.stringify(state));status.textContent=message}catch{status.textContent='No se pudo guardar. Prueba con imágenes más ligeras.'}}
  function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('images');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return dbPromise}
  async function putImage(file){if(!file?.type.startsWith('image/'))throw Error('Elige un archivo de imagen válido.');const d=await db(),key=`img-${Date.now()}-${Math.random().toString(36).slice(2)}`;await new Promise((ok,no)=>{const tx=d.transaction('images','readwrite');tx.objectStore('images').put(file,key);tx.oncomplete=ok;tx.onerror=()=>no(tx.error)});return key}
  async function getImage(key){if(!key)return '';const d=await db();return new Promise((ok,no)=>{const r=d.transaction('images').objectStore('images').get(key);r.onsuccess=()=>ok(r.result||null);r.onerror=()=>no(r.error)})}
  async function srcFor(item){if(item.imageKey){const blob=await getImage(item.imageKey);if(blob){const url=URL.createObjectURL(blob);objectUrls.push(url);return url}}return item.youtubeId?thumbFor(item.youtubeId):''}
  async function bannerSrc(){if(state.bannerKey){const b=await getImage(state.bannerKey);if(b){const u=URL.createObjectURL(b);objectUrls.push(u);return u}}return 'assets/banner-artesano.jpg'}
  function titleMarkup(value){const words=String(value||'').trim().split(/\s+/);if(words.length<2)return esc(value);return `${esc(words.slice(0,-1).join(' '))} <em>${esc(words.at(-1))}</em>`}
  function applyCopy(){const c=state.content.copy;$('#kicker').textContent=c.kicker;$('#title').innerHTML=titleMarkup(c.title);$('#heroText').textContent=c.heroText;$('#introKicker').textContent=c.introKicker;$('#introTitle').textContent=c.introTitle;$('#introText').textContent=c.introText;$('#collectionTitle').textContent=c.collectionTitle;document.title=`${c.title} — Wicho Nemes`;document.querySelectorAll('[data-copy]').forEach(el=>el.value=c[el.dataset.copy]??'');$('#adminSections').innerHTML=state.content.sections.map((section,i)=>`<label>Nombre de sección ${i+1}<input data-section="name" data-index="${i}" value="${esc(section.name)}"></label><label>Introducción ${i+1}<input data-section="intro" data-index="${i}" value="${esc(section.intro)}"></label>`).join('')}
  // Mosaico cerrado: piezas en bandas de una fila (todas con la misma altura).
  function mosaicWidths(count,shift=0){const patterns=[[6,3,3],[3,3,6]];const widths=[];let rest=count,turn=0;while(rest>0){if(rest===1){widths.push(12);break}if(rest===2){widths.push(6,6);break}const pattern=patterns[(turn+shift)%2];turn++;widths.push(...pattern);rest-=pattern.length}return widths}
  async function renderStories(){const content=state.content;$('#storyCount').textContent=String(content.stories.length).padStart(2,'0');$('#storyAdminCount').textContent=`(${content.stories.length})`;const groups=await Promise.all(content.sections.map(async(section,sectionIndex)=>{const list=content.stories.filter(item=>section.ids.includes(item.id));if(!list.length)return '';const widths=mosaicWidths(list.length,sectionIndex);const cards=await Promise.all(list.map(async(item,i)=>{const src=await srcFor(item);const cls=`w${widths[i]||3}`;const href=esc(safeUrl(item.url||watchUrl(item.youtubeId)));return `<article class="story-card ${cls}" data-id="${esc(item.id)}"><a class="story-image" href="${href}" ${href&&href!=='#'?'target="_blank" rel="noopener noreferrer"':''} aria-label="Ver pieza ${esc(item.title)} en YouTube"><img src="${esc(src)}" alt="${esc(item.title)}: ${esc(item.caption)}" loading="lazy" ${item.youtubeId&&!item.imageKey?`onerror="this.onerror=null;this.src='${esc(thumbFor(item.youtubeId,true))}'"`:''}><span class="story-play" aria-hidden="true">▶</span></a>${href&&href!=='#'?`<a class="story-open" href="${href}" target="_blank" rel="noopener noreferrer" aria-label="Ver pieza ${esc(item.title)}">↗</a>`:''}<div class="story-copy"><p class="story-tag"><b>${String(i+1).padStart(2,'0')}</b>${esc(item.category||section.name)}</p><h4>${esc(item.title)}</h4><p>${esc(item.caption)}</p></div></article>`}));return `<section class="story-section" aria-labelledby="section-${esc(section.id)}"><header class="story-section-head"><span>0${sectionIndex+1}</span><h3 id="section-${esc(section.id)}">${esc(section.name)}</h3><p>${esc(section.intro)}</p></header><div class="story-grid">${cards.join('')}</div></section>`}));$('#storySections').innerHTML=groups.join('')}
  async function renderAdmin(){const rows=await Promise.all(state.content.stories.map(async(item)=>`<div class="admin-row" draggable="true" data-id="${esc(item.id)}"><span class="grip" aria-hidden="true">⠿</span><img src="${esc(await srcFor(item))}" alt=""><div class="admin-fields"><input data-field="title" aria-label="Título" value="${esc(item.title)}"><input data-field="youtubeId" aria-label="ID de YouTube" value="${esc(item.youtubeId||'')}" placeholder="ID de YouTube"><textarea data-field="caption" aria-label="Historia" rows="2">${esc(item.caption)}</textarea><label class="replace-image">Cambiar portada<input type="file" data-image accept="image/*"></label></div><div class="row-actions"><button data-move="-1" aria-label="Mover arriba">↑</button><button data-move="1" aria-label="Mover abajo">↓</button><button class="delete" data-delete aria-label="Eliminar pieza">×</button></div></div>`));$('#adminList').innerHTML=rows.join('')}
  async function render(){objectUrls.forEach(URL.revokeObjectURL);objectUrls=[];applyCopy();$('#heroImage').src=await bannerSrc().catch(()=> 'assets/banner-artesano.jpg');await Promise.all([renderStories(),renderAdmin()]);document.dispatchEvent(new CustomEvent('wicho:render'))}
  function openAdmin(open){const panel=$('#adminPanel');panel.classList.toggle('is-open',open);panel.setAttribute('aria-hidden',String(!open));$('#adminToggle').setAttribute('aria-expanded',String(open));$('#adminBackdrop').hidden=!open;document.body.classList.toggle('admin-open',open);if(open)$('#adminClose').focus();else $('#adminToggle').focus()}
  $('#adminToggle').onclick=()=>openAdmin(true);$('#adminClose').onclick=()=>openAdmin(false);$('#adminBackdrop').onclick=()=>openAdmin(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#adminPanel').classList.contains('is-open'))openAdmin(false)});
  document.querySelectorAll('[data-copy]').forEach(el=>el.addEventListener('input',()=>{const pos=el.selectionStart;state.content.copy[el.dataset.copy]=el.value;applyCopy();try{el.setSelectionRange(pos,pos)}catch{}save()}));
  $('#adminSections').addEventListener('input',e=>{const i=Number(e.target.dataset.index),key=e.target.dataset.section;if(!key)return;state.content.sections[i][key]=e.target.value;const heading=$(`#section-${CSS.escape(state.content.sections[i].id)}`);if(heading)heading.textContent=state.content.sections[i].name;const intro=heading?.parentElement.querySelector('p');if(intro)intro.textContent=state.content.sections[i].intro;save()});
  $('#bannerInput').addEventListener('change',async e=>{try{state.bannerKey=await putImage(e.target.files[0]);save('Banner actualizado.');await render()}catch(err){status.textContent=err.message}});
  $('#addStory').addEventListener('click',async()=>{const title=$('#newTitle').value.trim(),youtubeId=$('#newYoutube').value.trim();if(!title||!youtubeId){status.textContent='Escribe un nombre y el ID de YouTube de la pieza.';return}try{const id=`custom-${Date.now()}`;const file=$('#newImage').files[0];const imageKey=file?await putImage(file):'';state.content.stories.push({id,title,category:'Nueva pieza',caption:$('#newCaption').value.trim()||'Una nueva pieza en movimiento.',youtubeId,...(imageKey?{imageKey}:{})});let dest=state.content.sections.find(s=>s.id==='especiales')||state.content.sections.at(-1);dest.ids.push(id);$('#newTitle').value='';$('#newYoutube').value='';$('#newCaption').value='';$('#newImage').value='';save('Pieza agregada al mosaico.');await render()}catch(err){status.textContent=err.message}});
  const list=$('#adminList');list.addEventListener('input',e=>{const row=e.target.closest('.admin-row'),field=e.target.dataset.field;if(!row||!field)return;const item=state.content.stories.find(s=>s.id===row.dataset.id);if(!item)return;item[field]=e.target.value;save();const card=$(`#storySections .story-card[data-id="${CSS.escape(item.id)}"]`);if(card){if(field==='title'){card.querySelector('h4').textContent=item.title;card.querySelector('img').alt=`${item.title}: ${item.caption}`}if(field==='caption'){card.querySelector('.story-copy p:last-child').textContent=item.caption;card.querySelector('img').alt=`${item.title}: ${item.caption}`}if(field==='category'){const tag=card.querySelector('.story-tag'),num=tag.querySelector('b');tag.innerHTML='';if(num)tag.appendChild(num);tag.appendChild(document.createTextNode(item.category||''))}if(field==='youtubeId')card.querySelector('.story-image').href=safeUrl(watchUrl(item.youtubeId))}});
  list.addEventListener('change',async e=>{const row=e.target.closest('.admin-row');if(!row)return;const item=state.content.stories.find(s=>s.id===row.dataset.id);if(e.target.matches('[data-image]')&&e.target.files[0]){try{item.imageKey=await putImage(e.target.files[0]);save('Portada reemplazada.');await render()}catch(err){status.textContent=err.message}}});
  list.addEventListener('click',e=>{const row=e.target.closest('.admin-row');if(!row)return;const id=row.dataset.id;if(e.target.closest('[data-move]')){const i=state.content.stories.findIndex(x=>x.id===id),n=i+Number(e.target.closest('[data-move]').dataset.move);if(n<0||n>=state.content.stories.length)return;[state.content.stories[i],state.content.stories[n]]=[state.content.stories[n],state.content.stories[i]];save('Orden actualizado; el mosaico se reorganizó.');render()}if(e.target.closest('[data-delete]')){state.content.stories=state.content.stories.filter(x=>x.id!==id);state.content.sections.forEach(s=>s.ids=s.ids.filter(x=>x!==id));save('Pieza eliminada.');render()}});
  let dragId='';list.addEventListener('dragstart',e=>{const r=e.target.closest('.admin-row');if(!r)return;dragId=r.dataset.id;r.classList.add('dragging');e.dataTransfer.setData('text/plain',dragId)});list.addEventListener('dragend',e=>e.target.closest('.admin-row')?.classList.remove('dragging'));list.addEventListener('dragover',e=>{if(e.target.closest('.admin-row'))e.preventDefault()});list.addEventListener('drop',e=>{const target=e.target.closest('.admin-row');if(!target||!dragId||dragId===target.dataset.id)return;e.preventDefault();const from=state.content.stories.findIndex(x=>x.id===dragId),to=state.content.stories.findIndex(x=>x.id===target.dataset.id),[item]=state.content.stories.splice(from,1);state.content.stories.splice(to,0,item);dragId='';save('Orden actualizado; el mosaico se reorganizó.');render()});
  $('#exportAdmin').onclick=async()=>{try{const keys=[state.bannerKey,...state.content.stories.map(s=>s.imageKey)].filter(Boolean),images={};for(const key of new Set(keys)){const blob=await getImage(key);if(blob)images[key]=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(r.error);r.readAsDataURL(blob)})}const data={format:'wicho-animacion-backup-v1',state,images},a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));a.download='respaldo-animacion-wicho.json';a.click();URL.revokeObjectURL(a.href);status.textContent='Respaldo descargado; puedes importarlo en otro dispositivo.'}catch(err){status.textContent=`No se pudo crear el respaldo: ${err.message}`}};
  $('#importAdmin').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const backup=JSON.parse(await file.text());if(backup.format!=='wicho-animacion-backup-v1'||!backup.state?.content?.stories)throw Error('Este archivo no es un respaldo de Animación válido.');const d=await db();await new Promise((ok,no)=>{const tx=d.transaction('images','readwrite');tx.objectStore('images').clear();tx.oncomplete=ok;tx.onerror=()=>no(tx.error)});for(const [key,data] of Object.entries(backup.images||{})){const blob=await fetch(data).then(r=>r.blob());await new Promise((ok,no)=>{const tx=d.transaction('images','readwrite');tx.objectStore('images').put(blob,key);tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}state=backup.state;save('Respaldo importado.');await render()}catch(err){status.textContent=`No se pudo importar: ${err.message}`}e.target.value=''});
  $('#resetAdmin').onclick=async()=>{if(!confirm('¿Restablecer los textos y las piezas originales de Animación?'))return;localStorage.removeItem(STORE);state={content:JSON.parse(JSON.stringify(defaults)),bannerKey:''};if(dbPromise){const d=await dbPromise;await new Promise(ok=>{const tx=d.transaction('images','readwrite');tx.objectStore('images').clear();tx.oncomplete=tx.onerror=ok})}save('Contenido original restaurado.');await render()};
  window.__wicho={get state(){return state},save,render,putImage,applyCopy,openAdmin,defaults,db};
  render();
})();
